vec4 Effect(vec2 uv) {
// Heart equation in polar coordinates: r = 1 - sin(theta)
vec2 q = uv * 2.0 - 1.0; // Convert to [-1, 1] space

float theta = atan(q.y, q.x);
float r = 1.0 - sin(theta);
float x = r * cos(theta) / 10.0;
float y = r * sin(theta) / 10.0;

// Calculate distance from heart boundary
float d = length(q - vec2(x, y));

// Create heart shape with color gradient
vec3 color = mix(
vec3(0.9, 0.1, 0.4), // Dark red for outside
vec3(1.0, 0.4, 0.6), // Light pink for inside
step(0.2, d) * (0.5 + 0.5 * sin(theta))
);

return vec4(color, 1.0);
}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // Time varying pixel color
    vec3 col = Effect(uv).rgb;//0.5 + 0.5*cos(iTime+uv.xyx+vec3(0,2,4));

    // Output to screen
    fragColor = vec4(col,1.0);
}
